sys_script_include.script:
function GetBusinessProcessRecord(vBP)
{
	var GetRecord = x_snc_devtools.GetRecord;
	var IsValidRecord = x_snc_devtools.IsValidRecord;

	var grBP = GetRecord('x_snc_agenticbpc_business_process',vBP);
	if (IsValidRecord(grBP) == true)
	{
		return grBP;
	}

	var grBP = new GlideRecord('x_snc_agenticbpc_business_process');
	var condition = grBP.addQuery('name','=',vBP);
	condition.addOrCondition('number','=',vBP);
	grBP.query();
	if (grBP.getRowCount() != 1)
	{
		return false;
	}
	grBP.next();
	if (IsValidRecord(grBP) == true)
	{
		return grBP;
	}
	return false;
}
